"""Origin framing and evidence audit extension.

The audit reads the concatenated parts of a capture as one HTTP/1.1 byte
stream, publishes the fully framed requests, attributes every request byte to
the capture part that supplied it and derives the paired evidence flags.
"""
import bisect
import re

from modules.byte_program import (byte_at, fingerprint, hash_range, leaf, merge,
                                   next_lf, read_range, fingerprint_bytes, MAX)

TOKEN = re.compile(rb"[!#$%&'*+.^_`|~0-9A-Za-z-]+\Z")

_MOD = 1 << 64
_MASK = _MOD - 1
_BASE = 257

MAX_REQUESTS = 20000
MAX_CHUNK_LINES = 40000
MAX_LINE = 8192
MAX_BLOCK = 65536
MAX_FIELDS = 128

_FORBIDDEN_TRAILER = (b'host', b'content-length', b'transfer-encoding')


class _Syntax(Exception):
    """Malformed capture bytes."""


class _Incomplete(Exception):
    """Capture bytes ended before the request was complete."""


class _Budget(object):
    """Shared audit budgets across all channels."""

    __slots__ = ('requests', 'chunk_lines')

    def __init__(self):
        self.requests = 0
        self.chunk_lines = 0

    def count_request(self):
        self.requests += 1
        if self.requests > MAX_REQUESTS:
            raise ValueError('request budget')

    def count_chunk_line(self):
        self.chunk_lines += 1
        if self.chunk_lines > MAX_CHUNK_LINES:
            raise ValueError('chunk line budget')


class _Hasher(object):
    """Incremental exact checksum of a byte sequence."""

    __slots__ = ('value', 'length')

    def __init__(self):
        self.value = 0
        self.length = 0

    def add_bytes(self, data):
        value = 0
        for byte in data:
            value = (value * _BASE + byte + 1) & _MASK
        self.value = (self.value * pow(_BASE, len(data), _MOD) + value) & _MASK
        self.length += len(data)

    def add_range(self, node, low, high):
        if high <= low:
            return
        segment = hash_range(node, low, high)
        self.value = (self.value * pow(_BASE, high - low, _MOD) + segment) & _MASK
        self.length += high - low

    def result(self):
        return {'n': self.length, 'h': '%016x' % self.value}


def _fields_fingerprint(fields):
    """Fingerprint of a field block: pair count then name/value pairs."""
    hasher = _Hasher()
    hasher.add_bytes(len(fields).to_bytes(8, 'big'))
    for name, value in fields:
        hasher.add_bytes(len(name).to_bytes(8, 'big'))
        hasher.add_bytes(name)
        hasher.add_bytes(len(value).to_bytes(8, 'big'))
        hasher.add_bytes(value)
    return hasher.result()


def _read_line(node, total, position):
    """Read one CRLF terminated line, returning ``(content, next_position)``."""
    remaining = total - position
    index = next_lf(node, position)
    if index < 0:
        if remaining <= MAX_LINE + 1:
            raise _Incomplete()
        raise _Syntax()
    if index - position > MAX_LINE + 1:
        raise _Syntax()
    if index == position:
        raise _Syntax()
    if byte_at(node, index - 1) != 13:
        raise _Syntax()
    return read_range(node, position, index - 1), index + 1


def _parse_field(line):
    """Split one header or trailer line into ``(name, trimmed_value)``."""
    index = line.find(b':')
    if index <= 0:
        raise _Syntax()
    name = line[:index]
    if TOKEN.match(name) is None:
        raise _Syntax()
    value = line[index + 1:]
    for byte in value:
        if byte == 9:
            continue
        if byte < 0x20 or byte > 0x7e:
            raise _Syntax()
    return name, value.strip(b' \t')


